                { ref: 'IOCL/REF/PR-2026-092', cust: 'Indian Oil Corp', prod: 'DN100 Gate Valve - HP', fac: 'Chennai', qty: 35, base: '2026-10-24', sim: '2026-11-02 (+9d)', opt: '2026-10-25 (+1d)', saved: '8 Days Saved', cell: 'MC-CHN-ASY-01', otd: 'On-Time Guaranteed' }
