                { ref: 'APSEZ/PROC/2026-0445', cust: 'Adani Ports', prod: 'DN50 Butterfly Valve', fac: 'Hyderabad', qty: 60, base: '2026-11-10', sim: '2026-11-18 (+8d)', opt: '2026-11-12 (+2d)', saved: '6 Days Saved', cell: 'MC-HYD-ASY-02', otd: 'Buffer Used' }
            ]
