                { ref: 'ONGC/OFF/2026-778', cust: 'ONGC Offshore', prod: 'Cryo Class 1500 Ball Valve', fac: 'Bengaluru', qty: 20, base: '2026-10-25', sim: '2026-11-04 (+10d)', opt: '2026-10-26 (+1d)', saved: '9 Days Saved', cell: 'MC-CHN-TST-01', otd: 'On-Time Guaranteed' }
            ]
        },
        'SIM-2026-005': {
            facility: 'Hyderabad', asset: 'MC-HYD-CNC-01', cat: 'workforce_constraint', duration: 40, cap: 60,
            baseline: 96.0, simulated: 75.0, optimized: 93.0, cost: '&#8377;14,000',
            rerouteFrom: 'Crew Shortage CNC Line 01', rerouteTo: 'Cross-Trained Assembly Staff Overtime',
            strategy: 'Cross-train Assembly technicians for secondary boring; run weekend overtime shift.',
            orders: [
                { ref: 'RELIANCE/JAM/2026-441', cust: 'Reliance Jamnagar', prod: '16\" Flanged Gate Valve', fac: 'Hyderabad', qty: 15, base: '2026-11-02', sim: '2026-11-10 (+8d)', opt: '2026-11-03 (+1d)', saved: '7 Days Saved', cell: 'MC-HYD-CNC-02', otd: 'Minor Delay Mitigated' }
            ]
        },
        'SIM-2026-006': {
            facility: 'Chennai', asset: 'MC-CHN-LAT-01', cat: 'material_shortage', duration: 60, cap: 75,
            baseline: 95.5, simulated: 70.0, optimized: 93.0, cost: '&#8377;28,000',
            rerouteFrom: 'Stellite Hardfacing Delay', rerouteTo: 'Alternate Alloy Vendor + Bengaluru Workload',
            strategy: 'Emergency stellite trim sourcing from alternate vendor; redistribute Chennai workload to Bengaluru assembly.',
            orders: [
                { ref: 'HPCL/VIZ/2026-334', cust: 'HPCL Vizag Refinery', prod: 'DN65 Globe Valve - Stellite', fac: 'Chennai', qty: 30, base: '2026-11-08', sim: '2026-11-16 (+8d)', opt: '2026-11-09 (+1d)', saved: '7 Days Saved', cell: 'MC-CHN-LAT-01', otd: 'On-Time Guaranteed' }
            ]
        },
        'SIM-2026-007': {
            facility: 'Hyderabad', asset: 'MC-HYD-CNC-02', cat: 'machine_breakdown', duration: 72, cap: 100,
            baseline: 96.5, simulated: 65.0, optimized: 92.0, cost: '&#8377;55,000',
            rerouteFrom: 'CNC-02 Lathe Overheat Alarm', rerouteTo: 'Concurrent Overtime (HYD-01 + BLR-01)',
            strategy: 'Emergency dual-reroute: CNC-01 + BLR-CNC-01 absorb critical path; concurrent overtime across Hyderabad and Bengaluru.',
            orders: [
                { ref: 'NTPC/THR/2026-891', cust: 'NTPC Thermal', prod: 'DN80 Gate Valve - HT', fac: 'Hyderabad', qty: 45, base: '2026-10-20', sim: '2026-11-05 (+16d)', opt: '2026-10-22 (+2d)', saved: '14 Days Saved', cell: 'MC-HYD-CNC-01 + BLR-CNC-01', otd: 'Minor Delay Mitigated' },
                { ref: 'GAIL/PIP/2026-223', cust: 'GAIL Pipeline', prod: 'DN50 Ball Valve - Std', fac: 'Hyderabad', qty: 55, base: '2026-11-01', sim: '2026-11-14 (+13d)', opt: '2026-11-03 (+2d)', saved: '11 Days Saved', cell: 'MC-BLR-CNC-01 (Rerouted)', otd: 'Buffer Used' }
            ]
        }
    };

    var currentFacilityFilter = 'ALL';
    var currentScenarioKey = 'SIM-2026-001';
    var isLiveStreaming = true;
    var liveTimer = null;

    /* ============================================================ */
    /* 1. TAB AND PAGE SWITCHING CONTROLLER                         */
    /* ============================================================ */
    function switchView(viewId, clickedLink) {
        document.querySelectorAll('.page-view').forEach(function(pv) {
            pv.classList.remove('active-view');
        });
        var targetView = document.getElementById(viewId);
        if (targetView) targetView.classList.add('active-view');

        document.querySelectorAll('.sidebar-link').forEach(function(sl) {
            sl.classList.remove('active');
        });

        if (clickedLink) {
            clickedLink.classList.add('active');
        } else {
            // Find sidebar link corresponding to view
            var map = {
                'view-overview': 'tab-overview',
                'view-pipeline': 'tab-pipeline',
                'view-simulator': 'tab-simulator',
                'view-machines': 'tab-machines',
                'view-analytics': 'tab-analytics',
                'view-orders': 'tab-orders'
            };
            var tabId = map[viewId];
            if (tabId) {
                var tab = document.getElementById(tabId);
                if (tab) tab.classList.add('active');
            }
        }

        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    /* ============================================================ */
    /* 2. FLEET HEALTH CALCULATION                                  */
    /* ============================================================ */
    function computeFleetHealth() {
        var total = 0, count = 0;
        machines.forEach(function(m) {
            if (currentFacilityFilter !== 'ALL' &amp;&amp; m.facility !== currentFacilityFilter) return;
            total += m.health; count++;
        });
        return count &gt; 0 ? (total / count).toFixed(1) : '0.0';
    }

    function updateHealthKPI() {
        var h = parseFloat(computeFleetHealth());
        var el = document.getElementById('kpiFleetHealth');
        if (!el) return;
        el.innerText = h + '%';
        el.style.color = h &gt; 85 ? '#10b981' : (h &gt; 75 ? '#f59e0b' : '#ef4444');
    }

    /* -- RENDER CATEGORIZED MACHINES (SEPARATE GROUPS and PROPER CARDS) -- */
    function renderMachines() {
        var gridMach = document.getElementById('gridMachining');
        var gridAsy  = document.getElementById('gridAssembly');
        var gridTst  = document.getElementById('gridTesting');
        var gridRwk  = document.getElementById('gridRework');

        if (gridMach) gridMach.innerHTML = '';
        if (gridAsy)  gridAsy.innerHTML = '';
        if (gridTst)  gridTst.innerHTML = '';
        if (gridRwk)  gridRwk.innerHTML = '';

        var activeSc = scenariosData[currentScenarioKey] || scenariosData['SIM-2026-001'];
        var countMach = 0, countAsy = 0, countTst = 0, countRwk = 0;

        machines.forEach(function(m) {
            if (currentFacilityFilter !== 'ALL' &amp;&amp; m.facility !== currentFacilityFilter) return;

            var card = document.createElement('div');
            card.className = 'portal-wc-card wc-' + m.status;

            var isImpacted = (m.code === activeSc.asset);
            var isRerouted = (m.code === 'MC-HYD-CNC-01' &amp;&amp; currentScenarioKey === 'SIM-2026-001');

            if (isImpacted) card.classList.add('wc-impacted');
            if (isRerouted) card.classList.add('wc-rerouted');

            var pillClass = 'pill-' + m.status;
            var pillText = m.status.toUpperCase();
            if (isImpacted) { pillClass = 'pill-repair'; pillText = 'DISRUPTED'; }
            else if (isRerouted) { pillClass = 'pill-optimal'; pillText = 'REROUTE ACTIVE'; }

            var loadColor = m.load &gt; 90 ? '#ef4444' : (m.load &gt; 80 ? '#f59e0b' : '#0284c7');
            var healthColor = m.health &gt; 85 ? '#16a34a' : (m.health &gt; 75 ? '#d97706' : '#dc2626');

            card.onclick = function() {
                selectMachineAsTarget(m.code, m.facility);
            };

            card.innerHTML =
                '<div>' +
                    '<div class="wc-top-row">' +
                        '<span class="wc-badge-code">' + m.code + ' &#8226; ' + m.facility + '</span>' +
                        '<span class="wc-status-pill ' + pillClass + '">' + pillText + '</span>' +
                    '</div>' +
                    '<div class="wc-name-title" title="' + m.name + '">' + m.name + '</div>' +
                    '<div class="wc-specs-table">' +
                        '<div class="wcs-item"><span class="wcs-label">Health</span><span class="wcs-val" style="color:' + healthColor + ';">' + m.health + '%</span></div>' +
                        '<div class="wcs-item"><span class="wcs-label">Spindle Temp</span><span class="wcs-val">' + m.temp + '&#176;C</span></div>' +
                        '<div class="wcs-item"><span class="wcs-label">Vibration</span><span class="wcs-val">' + m.vib + ' mm/s</span></div>' +
                        '<div class="wcs-item"><span class="wcs-label">Shift Crew</span><span class="wcs-val" style="font-size:11px;">' + m.crew.split(' ')[0] + ' ' + (m.crew.split(' ')[1] || '') + '</span></div>' +
                    '</div>' +
                '</div>' +
                '<div class="wc-load-row">' +
                    '<div class="wc-load-label-wrap"><span>Capacity Loading</span><strong style="font-family:var(--font-mono);color:' + loadColor + ';">' + m.load + '%</strong></div>' +
                    '<div class="wc-load-track"><div class="wc-load-fill" style="width:' + m.load + '%;background:' + loadColor + ';"></div></div>' +
                '</div>';

            if (m.category === 'Machining' &amp;&amp; gridMach) { gridMach.appendChild(card); countMach++; }
            else if (m.category === 'Assembly' &amp;&amp; gridAsy) { gridAsy.appendChild(card); countAsy++; }
            else if (m.category === 'Testing' &amp;&amp; gridTst) { gridTst.appendChild(card); countTst++; }
            else if (m.category === 'Rework' &amp;&amp; gridRwk) { gridRwk.appendChild(card); countRwk++; }
        });

        // Update counts on category headers
        var el;
        el = document.getElementById('countMachining'); if (el) el.innerText = countMach + ' Centers';
        el = document.getElementById('countAssembly');  if (el) el.innerText = countAsy + ' Centers';
        el = document.getElementById('countTesting');   if (el) el.innerText = countTst + ' Centers';
        el = document.getElementById('countRework');    if (el) el.innerText = countRwk + ' Center';

        // Toggle visibility of empty category blocks
        var bMach = document.getElementById('catBlockMachining'); if (bMach) bMach.style.display = countMach &gt; 0 ? 'block' : 'none';
        var bAsy  = document.getElementById('catBlockAssembly');  if (bAsy)  bAsy.style.display  = countAsy &gt; 0 ? 'block' : 'none';
        var bTst  = document.getElementById('catBlockTesting');   if (bTst)  bTst.style.display   = countTst &gt; 0 ? 'block' : 'none';
        var bRwk  = document.getElementById('catBlockRework');    if (bRwk)  bRwk.style.display    = countRwk &gt; 0 ? 'block' : 'none';

        updateHealthKPI();
    }

    /* ============================================================ */
    /* 4. ORDERS SCHEDULE RENDERING                                 */
    /* ============================================================ */
    function renderOrders() {
        var tbody = document.getElementById('orderTableBody');
        if (!tbody) return;
        tbody.innerHTML = '';
        var activeSc = scenariosData[currentScenarioKey] || scenariosData['SIM-2026-001'];

        activeSc.orders.forEach(function(o) {
            var tr = document.createElement('tr');
            tr.innerHTML =
                '<td style="font-family:var(--font-mono);font-weight:700;color:#0284c7;">' + o.ref + '</td>' +
                '<td><strong style="color:var(--text-heading);">' + o.cust + '</strong></td>' +
                '<td>' + o.prod + '</td>' +
                '<td><span class="tag-cell">' + o.fac + '</span></td>' +
                '<td style="font-family:var(--font-mono);font-weight:700;">' + o.qty + '</td>' +
                '<td>' + o.base + '</td>' +
                '<td style="color:#dc2626;font-family:var(--font-mono);font-weight:600;">' + o.sim + '</td>' +
                '<td style="color:#16a34a;font-family:var(--font-mono);font-weight:700;">' + o.opt + '</td>' +
                '<td><span class="tag-saved">' + o.saved + '</span></td>' +
                '<td><span class="tag-cell">' + o.cell + '</span></td>' +
                '<td><span class="tag-saved">' + o.otd + '</span></td>';
            tbody.appendChild(tr);
        });

        var rc = document.getElementById('orderRecoveryCount');
        if (rc) rc.innerHTML = activeSc.orders.length + ' Orders Recovered &#8226; 0 Days Net Loss';
        var topOrd = document.getElementById('kpiActiveOrders');
        if (topOrd) topOrd.innerText = activeSc.orders.length;
    }

    /* ============================================================ */
    /* 5. WHAT-IF SCENARIO LOADER & SIMULATION ENGINE               */
    /* ============================================================ */
    function loadScenario(scId) {
        currentScenarioKey = scId;
        var sc = scenariosData[scId];
        if (!sc) return;

        var el;
        el = document.getElementById('targetFacility'); if (el) el.value = sc.facility;
        updateAssetOptions();
        el = document.getElementById('targetAsset'); if (el) el.value = sc.asset;
        el = document.getElementById('disruptionCat'); if (el) el.value = sc.cat;
        el = document.getElementById('durationSlider'); if (el) el.value = sc.duration;
        el = document.getElementById('durationLabel'); if (el) el.innerText = sc.duration + 'h';
        el = document.getElementById('capacitySlider'); if (el) el.value = sc.cap;
        el = document.getElementById('capacityLabel'); if (el) el.innerText = sc.cap + '%';

        el = document.getElementById('kpiBaseline'); if (el) el.innerText = sc.baseline + '%';
        el = document.getElementById('kpiSimulated'); if (el) el.innerText = sc.simulated + '%';
        el = document.getElementById('kpiOptimized'); if (el) el.innerText = sc.optimized + '%';
        el = document.getElementById('strategyText'); if (el) el.innerText = sc.strategy;

        el = document.getElementById('barBaseline'); if (el) el.style.width = sc.baseline + '%';
        el = document.getElementById('barSimulated'); if (el) el.style.width = sc.simulated + '%';
        el = document.getElementById('barOptimized'); if (el) el.style.width = sc.optimized + '%';

        var drop = (sc.baseline - sc.simulated).toFixed(1);
        el = document.getElementById('kpiUnmitigatedDrop'); if (el) el.innerText = '-' + drop + '%';
        el = document.getElementById('kpiAdaptedOTD'); if (el) el.innerText = sc.optimized + '%';

        el = document.getElementById('stratRecovery'); if (el) el.innerText = '+' + (sc.optimized - sc.simulated).toFixed(1) + '%';
        el = document.getElementById('stratProtected'); if (el) el.innerText = sc.orders.length + ' VIP';
        el = document.getElementById('stratCost'); if (el) el.innerText = sc.cost;
        el = document.getElementById('analyticsDeltaCost'); if (el) el.innerText = sc.cost;

        el = document.getElementById('simRightSimOTD'); if (el) el.innerText = sc.simulated + '% OTD';
        el = document.getElementById('simRightOptOTD'); if (el) el.innerText = sc.optimized + '% OTD';

        renderMachines();
        renderOrders();
        showToast('Scenario Loaded: ' + scId);
    }

    function onDurationSlider(val) {
        var el = document.getElementById('durationLabel');
        if (el) el.innerText = val + 'h';
        recalcDynamicMitigation();
    }

    function onCapacitySlider(val) {
        var el = document.getElementById('capacityLabel');
        if (el) el.innerText = val + '%';
        recalcDynamicMitigation();
    }

    function recalcDynamicMitigation() {
        var dur = parseInt(document.getElementById('durationSlider').value, 10) || 48;
        var cap = parseInt(document.getElementById('capacitySlider').value, 10) || 100;

        var impactFactor = (dur / 120) * (cap / 100);
        var drop = (impactFactor * 26.5).toFixed(1);
        var base = 96.5;
        var sim = (base - drop).toFixed(1);
        var opt = (base - (drop * 0.12)).toFixed(1);
        var cost = Math.round(drop * 2000);

        var el;
        el = document.getElementById('kpiSimulated'); if (el) el.innerText = sim + '%';
        el = document.getElementById('barSimulated'); if (el) el.style.width = sim + '%';
        el = document.getElementById('kpiOptimized'); if (el) el.innerText = opt + '%';
        el = document.getElementById('barOptimized'); if (el) el.style.width = opt + '%';
        el = document.getElementById('kpiUnmitigatedDrop'); if (el) el.innerText = '-' + drop + '%';
        el = document.getElementById('kpiAdaptedOTD'); if (el) el.innerText = opt + '%';

        el = document.getElementById('stratRecovery'); if (el) el.innerText = '+' + (opt - sim).toFixed(1) + '%';
        el = document.getElementById('stratCost'); if (el) el.innerHTML = '&#8377;' + cost.toLocaleString('en-IN');
        el = document.getElementById('analyticsDeltaCost'); if (el) el.innerHTML = '&#8377;' + cost.toLocaleString('en-IN');

        el = document.getElementById('simRightSimOTD'); if (el) el.innerText = sim + '% OTD';
        el = document.getElementById('simRightOptOTD'); if (el) el.innerText = opt + '% OTD';
    }

    function onManualParamChange() {
        recalcDynamicMitigation();
    }

    function selectMachineAsTarget(code, fac) {
        var facSelect = document.getElementById('targetFacility');
        if (facSelect) facSelect.value = fac;
        updateAssetOptions();
        var assetSelect = document.getElementById('targetAsset');
        if (assetSelect) assetSelect.value = code;
        showToast('Selected target work center: ' + code);
        switchView('view-simulator');
    }

    function filterFacility(fac) {
        currentFacilityFilter = fac;
        document.querySelectorAll('.facility-btn').forEach(function(b) {
            b.classList.remove('active');
            if (b.getAttribute('data-facility') === fac) {
                b.classList.add('active');
            }
        });
        renderMachines();
        showToast('Plant Filter: ' + (fac === 'ALL' ? 'All Plants (12 Centers)' : fac + ' Plant Work Centers'));
    }

    function updateAssetOptions() {
        var fac = document.getElementById('targetFacility').value;
        var assetSelect = document.getElementById('targetAsset');
        if (!assetSelect) return;
        assetSelect.innerHTML = '';
        machines.forEach(function(m) {
            if (m.facility === fac) {
                var opt = document.createElement('option');
                opt.value = m.code;
                opt.innerText = m.code + ' (' + m.name.split(' ')[0] + ')';
                assetSelect.appendChild(opt);
            }
        });
        if (assetSelect.options.length &gt; 0) {
            assetSelect.selectedIndex = 0;
        }
    }

    function triggerSimulation() {
        var simEl = document.getElementById('kpiSimulated');
        var optEl = document.getElementById('kpiOptimized');
        if (simEl) simEl.style.opacity = '0.3';
        if (optEl) optEl.style.opacity = '0.3';

        setTimeout(function() {
            if (simEl) simEl.style.opacity = '1';
            if (optEl) optEl.style.opacity = '1';
            recalcDynamicMitigation();
            showToast('&#9889; Digital Twin Simulation complete! 95.0% OTD recovery calculated.');
        }, 600);
    }

    function commitMitigation() {
        showToast('&#10148; Adaptive mitigation schedule approved and released to production!');
    }

    function toggleTelemetry() {
        isLiveStreaming = !isLiveStreaming;
        var lbl = document.getElementById('telemetryLabel');
        var dot = document.getElementById('pulseDot');
        if (isLiveStreaming) {
            if (lbl) lbl.innerText = 'Live Telemetry (2.5s)';
            if (dot) dot.style.display = 'block';
            startHeartbeat();
            showToast('&#9654; Live telemetry streaming resumed.');
        } else {
            if (lbl) lbl.innerText = 'Telemetry Paused';
            if (dot) dot.style.display = 'none';
            clearInterval(liveTimer);
            showToast('&#10074;&#10074; Telemetry streaming paused.');
        }
    }

    function startHeartbeat() {
        clearInterval(liveTimer);
        liveTimer = setInterval(function() {
            if (!isLiveStreaming) return;
            machines.forEach(function(m) {
                if (m.status !== 'alert' &amp;&amp; m.status !== 'repair') {
                    m.temp = parseFloat((m.temp + (Math.random() * 0.4 - 0.2)).toFixed(1));
                }
            });
            renderMachines();
        }, 2500);
    }

    function showToast(msg) {
        var toast = document.getElementById('portalToast');
        var toastMsg = document.getElementById('portalToastMsg');
        if (!toast || !toastMsg) return;
        toastMsg.innerHTML = msg;
        toast.classList.add('show');
        setTimeout(function() { toast.classList.remove('show'); }, 3500);
    }

    function initDashboard() {
        try {
            renderMachines();
            renderOrders();
            startHeartbeat();
        } catch(e) {
            console.error('Init error:', e);
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initDashboard);
    } else {
        initDashboard();
    }


