      for (i = 0; i < wh.length; i++) {
        var L = wh[i]; if (L === D) continue;
        var s = db.stock(M, L), fr = Math.max(0, s.avail - s.safety), tr = transit(L, D);
        say('Step 3 ' + L + ': available ' + s.avail + ', safety ' + s.safety + ' (never used), importable ' + fr + ', transit ' + tr + 'd');
        if (fr > 0 && has(tr)) oth.push({ loc: L, free: fr, eta: tr });
      }
      oth.sort(byEta);
      for (i = 0; i < oth.length; i++) { t = take(oth[i].free); if (t > 0) add({ step: 'Transfer', from: oth[i].loc, qty: t, eta: oth[i].eta }); }
    }
    if (rem > 0) {
      var c = [], ol = db.supplierLead(M, D);
      if (has(ol)) c.push({ step: 'Supplier Direct', from: D, eta: ol });
      for (i = 0; i < wh.length; i++) {
        var W = wh[i]; if (W === D) continue;
        var sl = db.supplierLead(M, W), tw = transit(W, D);
        if (has(sl) && has(tw)) c.push({ step: 'Supplier via Warehouse', from: W, eta: sl + tw + cfg.transitBuffer, supplierEta: sl, transit: tw });
      }
      c.sort(function (a, b) { return (a.eta - b.eta) || (a.step === 'Supplier Direct' ? -1 : 1); });
      var best = c[0] || null;
      for (i = 0; i < c.length; i++) say('Step 4 route ' + c[i].step + ' via ' + c[i].from + ': arrives in ' + c[i].eta + 'd (need ' + need + 'd)');
      if (!best || best.eta > need) {
        var dn = [];
        for (i = 0; i < wh.length; i++) {
          var Q = wh[i]; if (Q === D) continue;
          var tq = transit(Q, D), sq = db.supplierLead(M, Q), rs = db.reservations(M, Q);
          for (j = 0; j < rs.length; j++) {
            var r = rs[j], why = null;
            if (r.inProduction) why = 'donor order already in production';
            else if (mat.critical && !cfg.allowCriticalPreempt) why = 'critical material';
            else if (r.priority - prio < cfg.priorityGap) why = 'our priority is not higher enough';
            else if (!has(tq) || tq > need) why = 'transfer too slow';
            else if (!has(sq) || sq + cfg.preemptBuffer > r.neededByDays) why = 'donor cannot rebuy in time (' + sq + 'd + buffer vs ' + r.neededByDays + 'd)';
            if (why) say('Step 5 preempt ' + Q + ' reservation ' + r.ref + ' refused: ' + why);
            else dn.push({ loc: Q, ref: r.ref, qty: r.qty, eta: tq, replEta: sq });
          }
        }
        dn.sort(byEta);
        for (i = 0; i < dn.length; i++) {
          t = take(dn[i].qty);
          if (t > 0) { add({ step: 'Preempt', from: dn[i].loc, qty: t, eta: dn[i].eta, ref: dn[i].ref, donorReplenish: { at: dn[i].loc, qty: t, eta: dn[i].replEta } }); say('Step 5 preempt ' + dn[i].loc + ' reservation ' + dn[i].ref + ': take ' + t + ', donor rebuys in ' + dn[i].replEta + 'd'); }
        }
      }
      if (rem > 0) {
        if (best) { var q = rem; add({ step: best.step, from: best.from, qty: q, eta: best.eta, supplierEta: best.supplierEta, transit: best.transit }); if (best.eta > need) say('Step 6 no route meets needed-by, best is late: planner task'); }
        else { failed = true; say('Step 6 no supplier route and no stock: FAILED, planner task'); }
      }
    }
    var late = false, pre = false, eta = 0, total = 0;
    for (i = 0; i < lines.length; i++) { late = late || lines[i].late; pre = pre || lines[i].step === 'Preempt'; eta = Math.max(eta, lines[i].eta); total += lines[i].cost; }
    var status = (failed || rem > 0) ? 'Failed' : late ? 'Late' : pre ? 'Needs Approval' : 'Ready';
    return { status: status, lines: lines, refill: refill, remaining: rem, eta: eta, cost: total, needsApproval: pre || late || failed || total > cfg.approvalValue, log: log };
  }
  function check(res, exp) {
    var e = [], i, s = [];
    for (i = 0; i < res.lines.length; i++) s.push(res.lines[i].step);
    if (exp.status && res.status !== exp.status) e.push('status ' + res.status + ' expected ' + exp.status);
    if (exp.steps && s.join(',') !== exp.steps.join(',')) e.push('steps [' + s.join(',') + '] expected [' + exp.steps.join(',') + ']');
    if (exp.qty) for (i = 0; i < exp.qty.length; i++) if (!res.lines[i] || res.lines[i].qty !== exp.qty[i]) e.push('line ' + i + ' qty ' + (res.lines[i] && res.lines[i].qty) + ' expected ' + exp.qty[i]);
    if (exp.from) for (i = 0; i < exp.from.length; i++) if (exp.from[i] && (!res.lines[i] || res.lines[i].from !== exp.from[i])) e.push('line ' + i + ' from ' + (res.lines[i] && res.lines[i].from) + ' expected ' + exp.from[i]);
    if (exp.refill && !res.refill) e.push('missing safety refill');
    if (exp.notFrom) for (i = 0; i < res.lines.length; i++) if (exp.notFrom.indexOf(res.lines[i].from) >= 0 && res.lines[i].step.indexOf('Supplier') < 0) e.push('used stock from forbidden ' + res.lines[i].from);
    return e;
  }
  return { plan: plan, check: check, DEFAULTS: DEFAULTS };
}
if (typeof module === 'object' && module.exports) module.exports = __SC_factory();
else if (typeof window === 'object') window.SourcingCore = __SC_factory();

        return exports;
    }

    function switchSimMode(mode) {
        var btnSrc = document.getElementById('btnModeSourcing');
        var btnFac = document.getElementById('btnModeFactory');
        var viewSrc = document.getElementById('viewSourcingWrap');
        var viewFac = document.getElementById('viewFactoryWrap');

        if (mode === 'sourcing') {
            if (btnSrc) btnSrc.classList.add('active');
            if (btnFac) btnFac.classList.remove('active');
            if (viewSrc) viewSrc.classList.add('active-view');
            if (viewFac) viewFac.classList.remove('active-view');
        } else {
            if (btnSrc) btnSrc.classList.remove('active');
            if (btnFac) btnFac.classList.add('active');
            if (viewSrc) viewSrc.classList.remove('active-view');
            if (viewFac) viewFac.classList.add('active-view');
        }
    }

    function updateSrcQtyLabel(val) {
        var el = document.getElementById('srcQtyBadge');
        if (el) el.innerText = val + ' units';
        solveCurrentSourcing();
    }

    function updateSrcNeedLabel(val) {
        var el = document.getElementById('srcNeedBadge');
        if (el) el.innerText = val + ' Days';
        solveCurrentSourcing();
    }

    function onSourcingParamChanged() {
        updateStockBreakdown();
        solveCurrentSourcing();
    }

    function updateStockBreakdown() {
        var matSelect = document.getElementById('srcMat');
        if (!matSelect) return;
        var mat = matSelect.value;

        var blr = 0, hyd = 0, maa = 0, quar = 0;
        if (SOURCING_DATA.stock) {
            SOURCING_DATA.stock.forEach(function(s) {
                if (s.material_product === mat) {
                    var avail = Math.max(0, s.total_quantity - s.reserved_quantity);
                    if (s.status === 'Quarantine') quar += s.total_quantity;
                    else if (s.location === 'WH-BLR') blr += avail;
                    else if (s.location === 'WH-HYD') hyd += avail;
                    else if (s.location === 'WH-MAA') maa += avail;
                }
            });
        }

        var elBLR = document.getElementById('stockValBLR');
        var elHYD = document.getElementById('stockValHYD');
        var elMAA = document.getElementById('stockValMAA');
        var elQUAR = document.getElementById('stockValQUAR');

        if (elBLR) elBLR.innerText = blr;
        if (elHYD) elHYD.innerText = hyd;
        if (elMAA) elMAA.innerText = maa;
        if (elQUAR) elQUAR.innerText = quar;

        var matInfo = SOURCING_DATA.mat.filter(function(m) { return m.material_product_id === mat; })[0];
        var badge = document.getElementById('srcMatCategoryBadge');
        if (badge && matInfo) {
            badge.innerText = (matInfo.material_type || 'RAW MATERIAL').toUpperCase();
        }
    }

    function initSourcingConsole() {
        try {
            _sourcingCoreEngine = __SC_factory();
            _sourcingDb = createJsonDb(SOURCING_DATA, SOURCING_CFG);

            // Populate Material Dropdown
            var matSelect = document.getElementById('srcMat');
            if (matSelect && matSelect.options.length === 0) {
                SOURCING_DATA.mat.forEach(function(m) {
                    var opt = document.createElement('option');
                    opt.value = m.material_product_id;
                    opt.textContent = m.material_product_id + ' - ' + m.name + ' (' + m.material_type + ')';
                    matSelect.appendChild(opt);
                });
            }

            // Render Preset Buttons S01..S10
            var container = document.getElementById('presetScenariosContainer');
            if (container && container.children.length === 0) {
                SOURCING_SCENARIOS.forEach(function(scen) {
                    var btn = document.createElement('button');
                    btn.className = 'preset-scen-btn';
                    btn.textContent = scen.id;
                    btn.title = scen.title + ': ' + scen.params.material + ' -> ' + scen.params.destination + ' (Qty: ' + scen.params.qty + ')';
                    btn.onclick = function() {
                        loadSourcingPreset(scen);
                    };
                    container.appendChild(btn);
                });
            }

            // Run initial default scenario (S01)
            if (SOURCING_SCENARIOS.length > 0) {
                loadSourcingPreset(SOURCING_SCENARIOS[0]);
            }
        } catch(e) {
            console.error('Error initializing Sourcing Console:', e);
        }
    }

    function loadSourcingPreset(scen) {
        var btns = document.querySelectorAll('.preset-scen-btn');
        btns.forEach(function(b) {
            if (b.textContent === scen.id) b.classList.add('active-scen');
            else b.classList.remove('active-scen');
        });

        var p = scen.params;
        var matSelect = document.getElementById('srcMat');
        if (matSelect) matSelect.value = p.material;

        var destSelect = document.getElementById('srcDest');
        if (destSelect) destSelect.value = p.destination;

        var priSelect = document.getElementById('srcPriority');
        if (priSelect) priSelect.value = p.priority || 2;

        var qtySlider = document.getElementById('srcQty');
        var qtyBadge = document.getElementById('srcQtyBadge');
        if (qtySlider) {
            qtySlider.value = p.qty;
            if (qtyBadge) qtyBadge.innerText = p.qty + ' units';
        }

        var needSlider = document.getElementById('srcNeed');
        var needBadge = document.getElementById('srcNeedBadge');
        if (needSlider) {
            needSlider.value = p.neededByDays;
            if (needBadge) needBadge.innerText = p.neededByDays + ' Days';
        }

        _currentTransferOverrides = p.transferOverride || {};

        updateStockBreakdown();
        solveCurrentSourcing();
    }

    function solveCurrentSourcing() {
        if (!_sourcingCoreEngine || !_sourcingDb) return;

        var mat = document.getElementById('srcMat').value;
        var dest = document.getElementById('srcDest').value;
        var priority = parseInt(document.getElementById('srcPriority').value, 10);
        var qty = parseInt(document.getElementById('srcQty').value, 10);
        var need = parseFloat(document.getElementById('srcNeed').value);

        var params = {
            material: mat,
            destination: dest,
            qty: qty,
            neededByDays: need,
            priority: priority,
            transferOverride: _currentTransferOverrides,
            dryRun: true
        };

        var result = _sourcingCoreEngine.plan(_sourcingDb, params, SOURCING_CFG.settings);
        renderSourcingPlan(result, need);
    }

    function renderSourcingPlan(result, need) {
        var statusBadge = document.getElementById('srcPlanStatusBadge');
        if (statusBadge) {
            statusBadge.className = 'tag-status';
            if (result.status === 'Ready') {
                statusBadge.classList.add('status-optimal');
                statusBadge.innerText = 'Ready';
            } else if (result.status === 'Needs Approval') {
                statusBadge.classList.add('status-warning');
                statusBadge.innerText = 'Needs Approval';
            } else if (result.status === 'Late') {
                statusBadge.classList.add('status-repair');
                statusBadge.innerText = 'Late Risk';
            } else {
                statusBadge.classList.add('status-alert');
                statusBadge.innerText = result.status;
            }
        }

        var totalQty = 0;
        var maxEta = 0;
        var totalCost = 0;

        if (result.lines && result.lines.length > 0) {
            result.lines.forEach(function(l) {
                totalQty += l.qty;
                if (l.eta > maxEta) maxEta = l.eta;
                var rate = (l.step === 'Supplier Direct') ? 50 : (l.step === 'Transfer' ? 25 : 5);
                totalCost += (l.qty * rate);
            });
        }

        var elTotal = document.getElementById('srcTotalQty');
        var elEta = document.getElementById('srcMaxEta');
        var elCost = document.getElementById('srcCostEst');

        if (elTotal) elTotal.innerText = totalQty;
        if (elEta) elEta.innerText = maxEta + ' Days';
        if (elCost) elCost.innerHTML = '&#8377;' + totalCost.toLocaleString('en-IN');

        var tbody = document.getElementById('srcAllocationTableBody');
        var tableHtml = '';
        if (result.lines && result.lines.length > 0) {
            result.lines.forEach(function(l) {
                var barWidth = Math.min(100, Math.round((l.eta / Math.max(maxEta, need, 1)) * 100));
                var markerPos = Math.min(100, Math.round((need / Math.max(maxEta, need, 1)) * 100));
                var lateClass = l.late ? 'late-bar' : '';

                tableHtml += '<tr>';
                tableHtml += '<td><strong>' + l.step + '</strong>' + (l.ref ? ' <span style="font-size:11px;color:#64748b;">(' + l.ref + ')</span>' : '') + '</td>';
                tableHtml += '<td>' + l.from + '</td>';
                tableHtml += '<td style="font-family:var(--font-mono);font-weight:700;">' + l.qty + '</td>';
                tableHtml += '<td style="font-family:var(--font-mono);font-weight:700;">' + l.eta + 'd</td>';
                tableHtml += '<td><div class="timeline-bar-wrap"><div class="timeline-bar-fill ' + lateClass + '" style="width:' + barWidth + '%;"></div><div class="timeline-bar-marker" style="left:' + markerPos + '%;" title="Deadline: ' + need + 'd"></div></div></td>';
                tableHtml += '</tr>';
            });
        } else {
            tableHtml = '<tr><td colspan="5" style="text-align:center;color:#ef4444;font-weight:700;">No feasible fulfillment route found under current constraints.</td></tr>';
        }
        tbody.innerHTML = tableHtml;

        var notices = document.getElementById('srcActionNoticesContainer');
        var noticeHtml = '';
        if (result.refill) {
            noticeHtml += '<div class="sourcing-action-notice">&#9888; Safety Stock Refill Triggered: Reorder <strong>' + result.refill.qty + ' units</strong> at ' + result.refill.at + ' (Supplier Lead Time: ' + result.refill.eta + ' days).</div>';
        }
        if (result.lines) {
            result.lines.forEach(function(l) {
                if (l.donorReplenish) {
                    noticeHtml += '<div class="sourcing-action-notice" style="background:#fef3c7;color:#b45309;border-color:#fde68a;">&#128260; Donor Rebuy Requirement: ' + l.donorReplenish.at + ' must reorder <strong>' + l.donorReplenish.qty + ' units</strong> within ' + l.donorReplenish.eta + ' days.</div>';
                }
            });
        }
        notices.innerHTML = noticeHtml;

        var logBox = document.getElementById('srcLogBox');
        if (result.log && result.log.length > 0) {
            logBox.textContent = result.log.join('\n');
        } else {
            logBox.textContent = 'Execution trace completed.';
        }
    }

    function commitSourcingOrder() {
        showPortalToast('&#10004; Sourcing plan approved and scheduled into ServiceNow Production Execution!');
    }
